"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  DataGridProvider,
  DataGridRoot,
  DataGridHeader,
  DataGridBody,
  defineColumns,
  type GridCommand,
  type Keymap,
} from "@/registry/default/components/data-grid/data-grid";
import { useDataGridKeybindings } from "@/registry/default/components/data-grid-keybindings/data-grid-keybindings";
import { Button } from "@/components/ui/button";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 150, flex: 2 },
  {
    id: "role",
    header: "Role",
    accessorKey: "role",
    type: "select",
    options: {
      choices: [
        "Admin",
        "User",
        "Editor",
        "Viewer",
        "Manager",
      ],
    },
    width: 120,
    flex: 1,
  },
  { id: "score", header: "Logins (30 days)", accessorKey: "score", type: "number", width: 90, flex: 1 },
] as const);

/**
 * A shortcuts dialog generated at runtime from the grid's effective keymap. Opens via the toolbar
 * button below or the `?` (shift+/) shortcut once focused in the grid. Also carries one custom
 * command (Save row, mod+s) to show how consumer commands join the keymap and the dialog.
 */
export default function DataGridKeybindingsDemo(): ReactNode {
  const rows = useMemo(() => generateDemoRows(6), []);
  const keys = useDataGridKeybindings();
  const [lastCommand, setLastCommand] = useState<string | null>(null);

  // A real consumer augments GridActions via declaration merging (like GridCellTypes); that
  // can't run inside this repo's tsc program (it would break the exhaustive GridAction test), so
  // the demo asserts the custom binding.
  const demoKeymap = { saveRow: ["mod+s"] } as Keymap;
  const commands = useMemo<Record<string, GridCommand<DemoRow>>>(
    () => ({
      saveRow: {
        label: "Save row",
        group: "editing",
        when: (ctx) => ctx.cell !== null,
        run: (ctx) => setLastCommand(`Saved ${ctx.row?.name ?? "no row"}`),
      },
    }),
    [],
  );

  return (
    <div className="w-full flex h-[300px] flex-col gap-2">
      <p className="text-sm text-muted-foreground">
        Click a cell to focus the grid, then press ? (shift+/) to open the shortcuts dialog — or use
        the button below. Mod+S runs the custom Save row command (listed in the dialog under
        Editing); its result shows below.
      </p>
      <Button variant="outline" size="sm" className="w-fit" onClick={keys.open}>
        Keyboard shortcuts
      </Button>
      {lastCommand && <p className="text-xs text-muted-foreground">{lastCommand}</p>}
      <div className="min-h-0 flex-1 overflow-hidden rounded-md border border-border">
        <DataGridProvider defaultData={rows} columns={columns} commands={commands} keymap={demoKeymap} plugins={[keys.plugin]}>
          <DataGridRoot className="h-full rounded-none border-none">
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
      </div>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const FIRST_NAMES = [
  "Ava", "Liam", "Mia", "Noah", "Priya", "Mateo", "Yuki", "Omar", "Elena", "Kofi",
  "Sofia", "Ravi", "Hannah", "Diego", "Amara", "Lukas", "Nadia", "Tomas", "Ingrid", "Jamal",
  "Chloe", "Arjun", "Fatima", "Ethan", "Leila", "Marco", "Zara", "Felix", "Mei", "Jonas",
  "Aisha", "Pavel", "Clara", "Hugo", "Nina", "Samir", "Alma", "Oskar", "Lucia", "Dev",
] as const;
const LAST_NAMES = [
  "Becker", "Okafor", "Nguyen", "Lindqvist", "Alvarez", "Tanaka", "Haddad", "Moreau", "Kowalski", "Joshi",
  "Rossi", "Teixeira", "Novak", "Fischer", "Mensah", "Larsen", "Castillo", "Ivanov", "Yamamoto", "Duarte",
  "Brennan", "Hoffmann", "Santos", "Kaya", "Weber", "Adeyemi", "Petrov", "Lopez", "Chen", "Murphy",
  "Bianchi", "Hartmann", "Ito", "Reyes", "Sorensen", "Qureshi", "Ferraz", "Dubois", "Park", "Svensson",
] as const;

/**
 * Generates `count` deterministic rows of a fictional user directory (seed 42, stable across renders).
 * `score` is the number of logins in the last 30 days.
 */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  const emailUses = new Map<string, number>();
  for (let i = 0; i < count; i++) {
    const first = FIRST_NAMES[Math.floor(next() * FIRST_NAMES.length)]!; // fixed non-empty literal arrays
    const last = LAST_NAMES[Math.floor(next() * LAST_NAMES.length)]!;
    const handle = `${first}.${last}`.toLowerCase();
    const uses = (emailUses.get(handle) ?? 0) + 1;
    emailUses.set(handle, uses);
    rows.push({
      id: `row-${i}`,
      name: `${first} ${last}`,
      email: `${handle}${uses > 1 ? uses : ""}@example.com`,
      age: Math.floor(next() * 44) + 21,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
